const results=await Promise.allSettled([
tools.exec_command({cmd:"cat regulatory-change-impact-brief/references/contracts.md; cat references/contracts.md","max_output_tokens":9000}),
tools.exec_command({cmd:"cat references/decision-log.md; rg -n -A18 -B4 '03:08|03:21' interviews/interview-B-3.md; cat docs/verification/u06.md; cat docs/u06-normalization.md","max_output_tokens":9000}),
tools.exec_command({cmd:"cat regulatory-change-impact-brief/scripts/run.py; cat regulatory-change-impact-brief/scripts/stage.py; cat regulatory-change-impact-brief/scripts/rci/runtime.py","max_output_tokens":11000})
]);results.forEach(text);

text(await tools.exec_command({cmd:"python3 - <<'PY'
import json
s=json.load(open('regulatory-change-impact-brief/references/schemas/contracts.schema.json'))['$defs']
for k in ['scope-state','capture-state','scope-basis','source','diagnostic','gap']:
 print(k,json.dumps(s.get(k),indent=2))
PY","max_output_tokens":6000}));

